CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at TEXT NOT NULL);
CREATE TABLE secret_metadata(id INTEGER PRIMARY KEY CHECK(id=1), ciphertext BLOB NOT NULL);
CREATE TABLE settings(id INTEGER PRIMARY KEY CHECK(id=1), version INTEGER NOT NULL, data TEXT NOT NULL);
CREATE TABLE principals(id TEXT PRIMARY KEY, credential_hash BLOB UNIQUE, permissions TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE access_tokens(id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id), token_hash BLOB NOT NULL UNIQUE, data TEXT NOT NULL, expires_at TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE admin_sessions(token_hash BLOB PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id), csrf TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE TABLE login_limits(address TEXT PRIMARY KEY, window_ms INTEGER NOT NULL, attempts INTEGER NOT NULL);
CREATE TABLE provider_accounts(id TEXT PRIMARY KEY, provider TEXT NOT NULL, data TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE provider_keys(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES provider_accounts(id), fingerprint TEXT NOT NULL UNIQUE, active_version TEXT NOT NULL, data TEXT NOT NULL, version INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE credential_versions(id TEXT PRIMARY KEY, key_id TEXT NOT NULL REFERENCES provider_keys(id), ciphertext BLOB NOT NULL, created_at TEXT NOT NULL, validity TEXT NOT NULL DEFAULT 'unknown');
CREATE TABLE runtime_gates(scope TEXT NOT NULL, entity_id TEXT NOT NULL, next_order INTEGER NOT NULL DEFAULT 0, cooldown_ms INTEGER NOT NULL DEFAULT 0, blocked INTEGER NOT NULL DEFAULT 0, validity TEXT NOT NULL DEFAULT 'unknown', failures INTEGER NOT NULL DEFAULT 0, window_ms INTEGER NOT NULL DEFAULT 0, breaker_ms INTEGER NOT NULL DEFAULT 0, half_open INTEGER NOT NULL DEFAULT 0, generation INTEGER NOT NULL DEFAULT 0, probe_owner TEXT NOT NULL DEFAULT '', PRIMARY KEY(scope,entity_id));
CREATE TABLE route_policies(capability TEXT NOT NULL, revision INTEGER NOT NULL, data TEXT NOT NULL, PRIMARY KEY(capability,revision));
CREATE TABLE budget_reservations(id TEXT PRIMARY KEY, parent_id TEXT NOT NULL, principal_id TEXT NOT NULL REFERENCES principals(id), account_id TEXT NOT NULL REFERENCES provider_accounts(id), key_id TEXT NOT NULL REFERENCES provider_keys(id), credential_version_id TEXT NOT NULL REFERENCES credential_versions(id), unit TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>=0), state TEXT NOT NULL DEFAULT 'held', active_slot INTEGER NOT NULL DEFAULT 0, capacity_basis TEXT NOT NULL DEFAULT 'none', created_at TEXT NOT NULL, account_gate_generation INTEGER NOT NULL DEFAULT 0, key_gate_generation INTEGER NOT NULL DEFAULT 0, UNIQUE(parent_id,id));
CREATE INDEX reservations_account ON budget_reservations(account_id,state);
CREATE INDEX reservations_principal ON budget_reservations(principal_id,active_slot);
CREATE TABLE usage_ledger(id TEXT PRIMARY KEY, source TEXT NOT NULL, event_kind TEXT NOT NULL, revision INTEGER NOT NULL, account_id TEXT NOT NULL REFERENCES provider_accounts(id), principal_id TEXT NOT NULL REFERENCES principals(id), unit TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>=0), certainty TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(source,event_kind,revision));
CREATE TABLE requests(id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id), data TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX requests_owner ON requests(principal_id,created_at DESC,id DESC);
CREATE TABLE attempts(id TEXT PRIMARY KEY, parent_id TEXT NOT NULL, attempt_number INTEGER NOT NULL, data TEXT NOT NULL, UNIQUE(parent_id,attempt_number));
CREATE TABLE usage_snapshots(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES provider_accounts(id), key_id TEXT, observed_at TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE research_jobs(id TEXT PRIMARY KEY, principal_id TEXT NOT NULL REFERENCES principals(id), provider TEXT NOT NULL, account_id TEXT NOT NULL REFERENCES provider_accounts(id), key_id TEXT NOT NULL REFERENCES provider_keys(id), credential_version_id TEXT NOT NULL REFERENCES credential_versions(id), state TEXT NOT NULL, upstream_id TEXT, data TEXT NOT NULL, input_cipher BLOB NOT NULL, result_cipher BLOB, execution_snapshot TEXT NOT NULL, next_poll_ms INTEGER NOT NULL DEFAULT 0, lease_token TEXT, lease_until_ms INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX research_upstream ON research_jobs(provider,account_id,upstream_id) WHERE upstream_id IS NOT NULL;
CREATE INDEX research_queue ON research_jobs(state,next_poll_ms);
CREATE INDEX research_owner ON research_jobs(principal_id,created_at DESC,id DESC);
CREATE TABLE idempotency_records(principal_id TEXT NOT NULL REFERENCES principals(id), operation TEXT NOT NULL, key_digest TEXT NOT NULL, intent_digest TEXT NOT NULL, replay_context TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES research_jobs(id), expires_at TEXT, PRIMARY KEY(principal_id,operation,key_digest));
CREATE TABLE job_events(id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES research_jobs(id), created_at TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE audit_events(id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, entity_id TEXT, created_at TEXT NOT NULL, data TEXT NOT NULL);
CREATE INDEX audit_order ON audit_events(created_at DESC,id DESC);
CREATE TABLE rate_windows(scope TEXT NOT NULL, entity_id TEXT NOT NULL, window_ms INTEGER NOT NULL, used INTEGER NOT NULL, PRIMARY KEY(scope,entity_id));
CREATE TABLE activity_fence(id INTEGER PRIMARY KEY CHECK(id=1), generation INTEGER NOT NULL);
INSERT INTO activity_fence VALUES(1,0);
